From 1f350f4bf88d1fbb67bf30d17fd74231417a5fa2 Mon Sep 17 00:00:00 2001
From: Razvan Crainea <razvan@opensips.org>
Date: Thu, 30 Aug 2018 18:26:29 +0300
Subject: [PATCH] dialog: fix unset_dlg_profile() linkers deletion

This commit fixes the following bugs introduced in commit 00cddf7:
1. when it was called, it was removing all the linkers of a dialog
2. it was not removing the actual linker it was called for, causing
constant increase in size for that specific profile (and leak)
3. when temporary copying the profiles list, the values were not copied,
thus they might have dissapeared when the actual cleanup was done.

Many thanks to Jonathan Hulme for reporting the issue and providing
testing framework for detecting the bug and testing the fix!

diff --git a/modules/dialog/dlg_profile.c b/modules/dialog/dlg_profile.c
index e7e76f8ae..50a6dbad4 100644
--- a/modules/dialog/dlg_profile.c
+++ b/modules/dialog/dlg_profile.c
@@ -572,40 +572,45 @@ void destroy_dlg_profiles(void)
 }

 /* array of temporary copies of the dialog profile linkers */
-static struct dlg_profile_link *tmp_linkers_arr, *tmp_linkers;
-static int n_tmp_linkers, tmp_linkers_size;
+static struct dlg_profile_link *tmp_linkers;

 static int init_tmp_linkers(struct dlg_cell *dlg)
 {
 	struct dlg_profile_link *l;
-	int i;
+	int i, len;
+	char *p;

-	for (l = dlg->profile_links, i = 0; l; l = l->next, i++) {
-		if (i == n_tmp_linkers) {
-			if (n_tmp_linkers == 0) {
-				tmp_linkers_size = sizeof *l;
-				n_tmp_linkers = 1;
-			} else {
-				tmp_linkers_size *= 2;
-				n_tmp_linkers *= 2;
-			}
-			tmp_linkers_arr = pkg_realloc(tmp_linkers_arr, tmp_linkers_size);
-			if (!tmp_linkers_arr) {
-				LM_ERR("No more pkg memory\n");
-				tmp_linkers = NULL;
-				return -1;
-			}
-		}
+	len = 0;
+
+	/* count the size we need to alocate */
+	for (l = dlg->profile_links, i = 0; l; l = l->next) {
+		len += sizeof *l;
+		if (l->profile->has_value)
+			len += l->value.len;
+		i++;
+	}

-		memcpy(&tmp_linkers_arr[i], l, sizeof *l);
+	tmp_linkers = pkg_malloc(len);
+	if (!tmp_linkers) {
+		LM_ERR("No more pkg memory\n");
+		return -1;
+	}
+
+	p = (char *)(tmp_linkers + i);
+	for (l = dlg->profile_links, i = 0; l; l = l->next, i++) {
+		memcpy(&tmp_linkers[i], l, sizeof *l);
 		if (i != 0)
-			tmp_linkers_arr[i-1].next = &tmp_linkers_arr[i];
+			tmp_linkers[i-1].next = &tmp_linkers[i];
+		if (l->profile->has_value) {
+			tmp_linkers[i].value.s = p;
+			memcpy(p, l->value.s, l->value.len);
+			p += l->value.len;
+		}
 	}

-	if (dlg->profile_links) {
-		tmp_linkers_arr[i-1].next = NULL;
-		tmp_linkers = &tmp_linkers_arr[0];
-	} else
+	if (dlg->profile_links)
+		tmp_linkers[i-1].next = NULL;
+	else
 		tmp_linkers = NULL;

 	return 0;
@@ -641,84 +646,97 @@ void destroy_linkers(struct dlg_cell *dlg, char is_replicated)
 	dlg_unlock_dlg(dlg);
 }

-/* this function should be called after destroy_linkers() and
- * with the dialog unlocked(can cause a deadlock otherwise) */
-void remove_dlg_prof_table(struct dlg_cell *dlg, char is_replicated)
+static void destroy_linker(struct dlg_profile_link *l, struct dlg_cell *dlg,
+		char is_replicated)
 {
+
 	map_t entry;
-	struct dlg_profile_link *l;
 	void ** dest;
-	struct dlg_profile_link *linker = tmp_linkers;
-
-	while(linker) {
-		l = linker;
-		linker = linker->next;
-		/* unlink from profile table */

-		if (!(l->profile->repl_type==REPL_CACHEDB)) {
-			lock_set_get( l->profile->locks, l->hash_idx);
+	if (!(l->profile->repl_type==REPL_CACHEDB)) {
+		lock_set_get( l->profile->locks, l->hash_idx);

-			if( l->profile->has_value)
+		if( l->profile->has_value)
+		{
+			entry = l->profile->entries[l->hash_idx];
+			dest = map_find( entry, l->value );
+			if( dest )
 			{
-				entry = l->profile->entries[l->hash_idx];
-				dest = map_find( entry, l->value );
-				if( dest )
+				prof_val_local_dec(dest, dlg);
+
+				if( *dest == 0 )
 				{
-					prof_val_local_dec(dest, dlg);
-
-					if( *dest == 0 )
-					{
-						/* warn everybody we are deleting */
-						/* XXX: we should queue these */
-						repl_prof_remove(&l->profile->name, &l->value);
-						map_remove(entry,l->value );
-					}
+					/* warn everybody we are deleting */
+					/* XXX: we should queue these */
+					repl_prof_remove(&l->profile->name, &l->value);
+					map_remove(entry,l->value );
 				}
 			}
-			else {
-				remove_local_counter(&l->profile->noval_local_counters[l->hash_idx], dlg);
-			}
+		}
+		else {
+			remove_local_counter(&l->profile->noval_local_counters[l->hash_idx], dlg);
+		}

-			lock_set_release( l->profile->locks, l->hash_idx  );
-		} else if (!is_replicated) {
-			if (!cdbc) {
-				LM_WARN("CacheDB not initialized - some information might"
-						" not be deleted from the cachedb engine\n");
-				continue;
-			}
+		lock_set_release( l->profile->locks, l->hash_idx  );
+	} else if (!is_replicated) {
+		if (!cdbc) {
+			LM_WARN("CacheDB not initialized - some information might"
+					" not be deleted from the cachedb engine\n");
+			return;
+		}

-			/* prepare buffers */
-			if( l->profile->has_value) {
-
-				if (dlg_fill_value(&l->profile->name, &l->value) < 0)
-					continue;
-				if (dlg_fill_size(&l->profile->name) < 0)
-					continue;
-				/* not really interested in the new val */
-				if (cdbf.sub(cdbc, &dlg_prof_val_buf, 1,
-							profile_timeout, NULL) < 0) {
-					LM_ERR("cannot remove profile from CacheDB\n");
-					continue;
-				}
-				/* fill size into name */
-				if (cdbf.sub(cdbc, &dlg_prof_size_buf, 1,
-							profile_timeout, NULL) < 0) {
-					LM_ERR("cannot remove size profile from CacheDB\n");
-					continue;
-				}
-			} else {
-				if (dlg_fill_name(&l->profile->name) < 0)
-					continue;
-				if (cdbf.sub(cdbc, &dlg_prof_noval_buf, 1,
-							profile_timeout, NULL) < 0) {
-					LM_ERR("cannot remove profile from CacheDB\n");
-					continue;
-				}
+		/* prepare buffers */
+		if( l->profile->has_value) {
+
+			if (dlg_fill_value(&l->profile->name, &l->value) < 0)
+				return;
+			if (dlg_fill_size(&l->profile->name) < 0)
+				return;
+			/* not really interested in the new val */
+			if (cdbf.sub(cdbc, &dlg_prof_val_buf, 1,
+					profile_timeout, NULL) < 0) {
+				LM_ERR("cannot remove profile from CacheDB\n");
+				return;
+			}
+			/* fill size into name */
+			if (cdbf.sub(cdbc, &dlg_prof_size_buf, 1,
+					profile_timeout, NULL) < 0) {
+				LM_ERR("cannot remove size profile from CacheDB\n");
+				return;
+			}
+		} else {
+			if (dlg_fill_name(&l->profile->name) < 0)
+				return;
+			if (cdbf.sub(cdbc, &dlg_prof_noval_buf, 1,
+					profile_timeout, NULL) < 0) {
+				LM_ERR("cannot remove profile from CacheDB\n");
+				return;
 			}
 		}
 	}
 }

+/* this function should be called after destroy_linkers() and
+ * with the dialog unlocked(can cause a deadlock otherwise) */
+void remove_dlg_prof_table(struct dlg_cell *dlg, char is_replicated)
+{
+	struct dlg_profile_link *l;
+	struct dlg_profile_link *linker = tmp_linkers;
+
+	while(linker) {
+		l = linker;
+		linker = linker->next;
+		/* unlink from profile table */
+
+		destroy_linker(l, dlg, is_replicated);
+	}
+	/* removed what we had to - we can release the tmp linkers */
+	if (tmp_linkers) {
+		pkg_free(tmp_linkers);
+		tmp_linkers = NULL;
+	}
+}
+
 inline static unsigned int calc_hash_profile( str *value, struct dlg_cell *dlg,
 										struct dlg_profile_table *profile )
 {
@@ -904,10 +922,8 @@ int unset_dlg_profile(struct dlg_cell *dlg, str *value,
 			 */
 		}
 	}
-	if (dlg->locked_by!=process_no) {
-		dlg->locked_by = 0;
+	if (dlg->locked_by!=process_no)
 		dlg_unlock( d_table, d_entry);
-	}
 	return -1;

 found:
@@ -921,13 +937,10 @@ found:
 	linker->next = NULL;
 	dlg->flags |= DLG_FLAG_VP_CHANGED;

-	/* remove linkers from dialog */
-	destroy_linkers_unsafe(dlg, 0);
-
 	if (dlg->locked_by!=process_no)
 		dlg_unlock( d_table, d_entry);

-	remove_dlg_prof_table(dlg, 0);
+	destroy_linker(linker, dlg, 0);

 	return 1;
 }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug was due to improper handling of dialog profile linkers in the `unset_dlg_profile` function. Specifically, the function was removing all linkers from a dialog without correctly unlinking the specific linker it was called for, leading to a memory leak as the size of the profile increased without proper cleanup. Additionally, the temporary copying of the profiles list did not correctly copy the values, causing them to disappear during cleanup.

        Commit message:
        dialog: fix unset_dlg_profile() linkers deletion

This commit fixes the following bugs introduced in commit 00cddf7:
1. when it was called, it was removing all the linkers of a dialog
2. it was not removing the actual linker it was called for, causing
constant increase in size for that specific profile (and leak)
3. when temporary copying the profiles list, the values were not copied,
thus they might have dissapeared when the actual cleanup was done.

Many thanks to Jonathan Hulme for reporting the issue and providing
testing framework for detecting the bug and testing the fix!  

